@startuml

class User {
  + userId : string
  + name : string
  + address : string
  + birthday : date
}

abstract class BusinessOwner {
  + linkedinAccount : string
}

abstract class HungryCustomer {
  + deliveryAddress : string
}

abstract class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Min : double
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + orderId : string
  + orderDateTime : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder {
  + entertainmentType : string
  + duration : time
}

class Availability {
  + day : string
}

User --|> BusinessOwner
User --|> HungryCustomer
User --|> Entertainer

BusinessOwner "1" *-- "1..*" PizzaRestaurant : owns
PizzaRestaurant "1" *-- "1..*" Pizza : offers
HungryCustomer "1" -- "0..*" Order : places
Order "1" *-- "1..*" Pizza : contains
Order "1" -- "0..1" EntertainmentOrder : is_a
EntertainmentOrder "*" -- "1" Entertainer : fulfilled_by
Entertainer "1" o-- "1..*" Availability : works_at
Availability "*" -- "1" PizzaRestaurant : for_restaurant

@enduml

